query aiSecurityEndUsersSessionConversation ( $accountId:ID! $aiSecurityEndUsersSessionConversationInput:AiSecurityEndUsersSessionConversationInput!) {
	aiSecurity ( accountId:$accountId ) {
		endUsers {
			sessionConversation ( input:$aiSecurityEndUsersSessionConversationInput   ) {
				userPrompt
				llmResponse
			}
		}
	}	
}
